GardenBorderEdgerMaker.ironStock=16; GardenBorderEdgerMaker.bronzeStock=12; GardenBorderEdgerMaker.woodStock=14; GardenBorderEdgerMaker.leatherStock=8; GardenBorderEdgerMaker.silverStock=8; GardenBorderEdgerMaker.goldStock=6; GardenBorderEdgerMaker.jewelStock=4; GardenBorderEdgerMaker.pearlStock=4
