function GardenBorderEdgerMaker.init() GardenBorderEdgerMaker.ironStock=16; GardenBorderEdgerMaker.bronzeStock=12; GardenBorderEdgerMaker.woodStock=14; GardenBorderEdgerMaker.leatherStock=8; GardenBorderEdgerMaker.silverStock=8; GardenBorderEdgerMaker.goldStock=6; GardenBorderEdgerMaker.jewelStock=4; GardenBorderEdgerMaker.pearlStock=4; GardenBorderEdgerMaker.productStock={}; GardenBorderEdgerMaker.buildings={}; GardenBorderEdgerMaker.maker=nil; GardenBorderEdgerMaker.activeMaking={}; GardenBorderEdgerMaker.totalProducts=0; GardenBorderEdgerMaker.dayTimer=0; print("[GardenBorderEdgerMaker] Royal Garden Border Edger Maker System initialized (6 products, 4 buildings)") end
function GardenBorderEdgerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenBorderEdgerMaker.maker={name=n or ("Robnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Robnik najet: %s (spretnost: %d)",GardenBorderEdgerMaker.maker.name,s),"success") end; return true end
function GardenBorderEdgerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenBorderEdgerMaker.build(id) local ok,e=GardenBorderEdgerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenBorderEdgerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenBorderEdgerMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenBorderEdgerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenBorderEdgerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenBorderEdgerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenBorderEdgerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenBorderEdgerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenBorderEdgerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenBorderEdgerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenBorderEdgerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenBorderEdgerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenBorderEdgerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenBorderEdgerMaker.buildings==0 then return false,"Potrebna robna delavnica" end; if not GardenBorderEdgerMaker.maker then return false,"Potreben robnik" end; return true end
function GardenBorderEdgerMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenBorderEdgerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenBorderEdgerMaker.ironStock=GardenBorderEdgerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenBorderEdgerMaker.bronzeStock=GardenBorderEdgerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenBorderEdgerMaker.woodStock=GardenBorderEdgerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenBorderEdgerMaker.leatherStock=GardenBorderEdgerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenBorderEdgerMaker.silverStock=GardenBorderEdgerMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenBorderEdgerMaker.goldStock=GardenBorderEdgerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenBorderEdgerMaker.jewelStock=GardenBorderEdgerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenBorderEdgerMaker.pearlStock=GardenBorderEdgerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenBorderEdgerMaker.maker then t=math.max(1,t-math.floor(GardenBorderEdgerMaker.maker.skill/13)) end; table.insert(GardenBorderEdgerMaker.activeMaking,{id="gardenborderedger_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenBorderEdgerMaker.completeMaking(m) local q=1.0+(GardenBorderEdgerMaker.getQualityBonus()/100); if GardenBorderEdgerMaker.maker then q=q+(GardenBorderEdgerMaker.maker.skill/140) end; q=math.min(2.5,q); GardenBorderEdgerMaker.productStock[m.productType]=(GardenBorderEdgerMaker.productStock[m.productType] or 0)+m.quantity; GardenBorderEdgerMaker.totalProducts=GardenBorderEdgerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenBorderEdgerMaker.maker then GardenBorderEdgerMaker.maker.itemsMade=GardenBorderEdgerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenBorderEdgerMaker.maker.skill=math.min(100,GardenBorderEdgerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Robnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardenborderedger.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenBorderEdgerMaker.update(dt) if not _G.state then return end; GardenBorderEdgerMaker.dayTimer=GardenBorderEdgerMaker.dayTimer+dt; if GardenBorderEdgerMaker.dayTimer>=30 then GardenBorderEdgerMaker.dayTimer=0; for i=#GardenBorderEdgerMaker.activeMaking,1,-1 do local m=GardenBorderEdgerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenBorderEdgerMaker.completeMaking(m); table.remove(GardenBorderEdgerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenBorderEdgerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenBorderEdgerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenBorderEdgerMaker.getStats() return {ironStock=GardenBorderEdgerMaker.ironStock,bronzeStock=GardenBorderEdgerMaker.bronzeStock,woodStock=GardenBorderEdgerMaker.woodStock,leatherStock=GardenBorderEdgerMaker.leatherStock,silverStock=GardenBorderEdgerMaker.silverStock,goldStock=GardenBorderEdgerMaker.goldStock,jewelStock=GardenBorderEdgerMaker.jewelStock,pearlStock=GardenBorderEdgerMaker.pearlStock,productStock=GardenBorderEdgerMaker.productStock,numBuildings=#GardenBorderEdgerMaker.buildings,hasMaker=GardenBorderEdgerMaker.maker~=nil,makerName=GardenBorderEdgerMaker.maker and GardenBorderEdgerMaker.maker.name or "—",makerSkill=GardenBorderEdgerMaker.maker and GardenBorderEdgerMaker.maker.skill or 0,activeMaking=#GardenBorderEdgerMaker.activeMaking,totalProducts=GardenBorderEdgerMaker.totalProducts} end
return GardenBorderEdgerMaker
